INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 4, 'theory', 'Quiz: Searching and Sorting');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 0, 'Why doesn''t binary search work on a linked list, even a sorted one?', '["Because lists don''t support comparing elements", "Because a list can''t be traversed twice", "Because reaching the middle takes a linear walk — all the savings evaporate", "Because binary search works only with numbers"]', 2, 'The trick rests on two requirements: sorted order and constant-time access to any element. The same pairing underlies database indexes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 1, 'On almost sorted data, which elementary sort runs in nearly linear time?', '["Selection: the fewest swaps", "Insertion: each element moves one or two positions", "Bubble: uniform swaps of neighbors", "None: quadratic is quadratic"]', 1, 'That is why insertion sort lives inside library hybrids like Timsort and introsort: on small and almost ordered pieces it rules.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 2, 'An order list is sorted by date; now we sort it by city. What does a stable sort give us?', '["The chronology of orders is preserved within each city", "The sort runs faster on already ordered data", "Duplicate orders are removed", "The date order is preserved for the whole table at once"]', 0, 'Elements equal by city keep their original order. Stability is a tool, not a detail: in the documentation of library sorts it is always stated explicitly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 3, 'What is the essence of "binary search on the answer"?', '["Looking up a value by binary search in a sorted data array", "Sorting the answers and comparing neighbors", "Trying all possible answers from smallest to largest", "If a value works, every smaller one works too — so we binary-search the space of answers with a linear check"]', 3, 'The answer is monotonic, so instead of brute force we narrow the range: a logarithmic number of iterations, each check linear. The pattern solves a whole class of problems that look like brute-force monsters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 4, 'Why is the ability to merge two sorted lists more valuable than merge sort itself?', '["Because merging needs no extra memory", "Because merging is more stable than other operations", "Because merging is needed everywhere: logs of two services, list intersection, external sorting of data from disk", "Because merging works only on magnetic tapes"]', 2, 'Scaling the technique up gives external sorting: sort chunks that fit in memory and merge ever larger runs. The principle hasn''t changed in half a century.');
